class Solution:
    def pieceSizes(self, s: str) -> List[int]:
        sizes = []
        start = end = 0
        for i, ch in enumerate(s):
            end = max(end, s.rindex(ch))
            if i == end:
                sizes.append(end - start + 1)
                start = i + 1
        return sizes

